def apply_channel(K, rho, sys=None, dim=None):
    if sys is None:
        sys = list(range(len(dim)))
    if dim is None:
        dim = [rho.shape[0]**(1/len(rho.shape))]*len(rho.shape)

    identity_matrices = [np.eye(d, dtype=float) for d in dim]

    matrix = np.zeros_like(rho, dtype=float)

    for kraus in K:
        for subsystem in sys:
            kraus_on_subsystem = list(identity_matrices)
            kraus_on_subsystem[subsystem] = kraus
            combined_kraus = tensor(*kraus_on_subsystem)
            matrix += combined_kraus @ rho @ combined_kraus.conj().T

    return matrix
