def Rlnm(l, n, m, k, z, N_t):
    from scipy.special import sph_bess
    import numpy as np

    # Initialize the translation coefficients array
    Rlmn = np.zeros((N_t, N_t, N_t), dtype=complex)

    # Calculate the initial condition using Spherical Bessel Function of the First Kind
    for l in range(N_t):
        Rlmn[l, 0, 0] = (-1)**l * np.sqrt(2*l + 1) * sph_bess(l, k*z)

    # Define the coefficients a_n^m and b_n^m
    def a_nm(n, m):
        if n < abs(m):
            return 0
        else:
            return np.sqrt((n + 1 + abs(m)) * (n + 1 - abs(m)) / ((2 * n + 1) * (2 * n + 3)))

    def b_nm(n, m):
        if n < abs(m):
            return 0
        elif 0 <= m <= n:
            return np.sqrt((n - m - 1) * (n - m) / ((2 * n - 1) * (2 * n + 1)))
        else:
            return -np.sqrt((n - m - 1) * (n - m) / ((2 * n - 1) * (2 * n + 1)))

    # Recursion process for (R|R)lmn
    for l in range(1, N_t):
        for m in range(-l, l + 1):
            for n in range(max(0, abs(m)), N_t):
                if m == -l:
                    Rlmn[l, n, m] = b_nm(l, m) * Rlmn[l-1, n, m+1] - b_nm(l+1, m) * Rlmn[l+1, n, m]
                else:
                    Rlmn[l, n, m] = (a_nm(n-1, m) * Rlmn[l, n-1, m] - a_nm(n, m) * Rlmn[l, n+1, m]) / a_nm(l, m)

    return Rlmn[l, n, m]
