def Strang_splitting(u, dt, dx, alpha):
    import numpy as np

    def second_diff(target, u, dx):
        if target == 0:
            u = np.concatenate(([u[0]], u))
            target += 1
        elif target == len(u) - 1:
            u = np.concatenate((u, [u[-1]]))
        deriv = (u[target + 1] - 2 * u[target] + u[target - 1]) / dx**2
        return deriv

    u_hat = u.copy()
    for i in range(1, len(u) - 1):
        u_hat[i] += 0.5 * dt * second_diff(i, u, dx)

    u_tilde = u_hat.copy()
    for i in range(1, len(u) - 1):
        u_tilde[i] += dt * alpha * second_diff(i, u_hat, dx)

    u_check = u_tilde.copy()
    for i in range(1, len(u) - 1):
        u_check[i] += 0.5 * dt * second_diff(i, u_tilde, dx)

    return u_check
