                    (temp_grid[t-1, i+1, j] - 2*temp_grid[t-1, i, j] + temp_grid[t-1, i-1, j]) / (diff_grid[i, j])**2 +
                    (temp_grid[t-1, i, j+1] - 2*temp_grid[t-1, i, j] + temp_grid[t-1, i, j-1]) / (diff_grid[i, j])**2
