def apply_channel(K, rho, sys=None, dim=None):
    if sys is None:
        sys = list(range(len(dim)))

    if dim is None:
        dim = [rho.shape[0]]

    full_dim = np.prod(dim)
    identity_matrix = np.eye(full_dim)

    for i, Ki in enumerate(K):
        operator = identity_matrix.copy()
        for s in sys:
            if s == 0:
                operator = np.kron(Ki, operator)
            else:
                operator = np.kron(np.eye(np.prod(dim[:s])), operator)
            if s < len(dim) - 1:
                operator = np.kron(operator, np.eye(np.prod(dim[s+1:])))

        rho = operator @ rho @ operator.conj().T

    return rho
